{"id":"31e2e6b5-c577-40af-b2a6-197c4ed8de2f","inserted_at":"2026-07-07T17:42:24.04689+00:00","updated_at":"2026-07-07T17:42:24.04689+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- ============================================================\r\n-- BLOCCO 3A: Viste SQL\r\n-- ============================================================\r\n\r\n-- 1. Eventi attivi per tenant\r\nCREATE OR REPLACE VIEW active_tenant_events AS\r\nSELECT * FROM tenant_events\r\nWHERE status = 'active'\r\n  AND starts_at <= now()\r\n  AND ends_at >= now()\r\nORDER BY ends_at;\r\n\r\n-- 2. Progresso sfide collettive\r\nCREATE OR REPLACE VIEW goal_progress AS\r\nSELECT \r\n    g.id,\r\n    g.title,\r\n    g.target_value,\r\n    g.current_value,\r\n    ROUND(g.current_value::numeric / NULLIF(g.target_value, 0) * 100, 1) AS progress_pct,\r\n    g.status,\r\n    COUNT(gp.user_id) AS participants_count\r\nFROM collective_goals g\r\nLEFT JOIN goal_participations gp ON g.id = gp.goal_id\r\nGROUP BY g.id;\r\n\r\n-- 3. Classifica impatto globale (formula calibrata)\r\nCREATE OR REPLACE VIEW global_impact_leaderboard AS\r\nSELECT \r\n    p.id AS user_id,\r\n    p.nickname,\r\n    p.total_co2,\r\n    p.total_tokens,\r\n    COALESCE(c.verified_reports, 0) AS verified_reports,\r\n    COALESCE(s.validated_scans_30d, 0) AS recent_scans,\r\n    (COALESCE(s.validated_scans_30d, 0) * 1) +\r\n    (p.total_tokens * 0.1) +\r\n    (COALESCE(c.verified_reports, 0) * 5) +\r\n    (COALESCE(p.total_co2, 0) * 0.01) AS impact_score,\r\n    ROW_NUMBER() OVER (ORDER BY \r\n        (COALESCE(s.validated_scans_30d, 0) * 1) +\r\n        (p.total_tokens * 0.1) +\r\n        (COALESCE(c.verified_reports, 0) * 5) +\r\n        (COALESCE(p.total_co2, 0) * 0.01) DESC\r\n    ) AS rank\r\nFROM profiles p\r\nLEFT JOIN (\r\n    SELECT user_id, COUNT(id) AS verified_reports\r\n    FROM civic_reports\r\n    WHERE status IN ('confirmed', 'verified', 'resolved')\r\n    GROUP BY user_id\r\n) c ON p.id = c.user_id\r\nLEFT JOIN (\r\n    SELECT user_id, COUNT(id) AS validated_scans_30d\r\n    FROM discoveries\r\n    WHERE discovered_at > now() - interval '30 days'\r\n    GROUP BY user_id\r\n) s ON p.id = s.user_id\r\nORDER BY impact_score DESC;\r\n\r\n-- 4. Badge completi utente\r\nCREATE OR REPLACE VIEW user_badges_complete AS\r\nSELECT \r\n    p.id AS user_id,\r\n    p.nickname,\r\n    (SELECT COUNT(*) FROM user_badges WHERE user_id = p.id AND badge_template_id IN (SELECT id FROM badge_templates WHERE category = 'civic_commitment')) AS commitment_badges,\r\n    (SELECT COUNT(*) FROM user_badges WHERE user_id = p.id AND badge_template_id IN (SELECT id FROM badge_templates WHERE category = 'civic_impact')) AS impact_badges,\r\n    (SELECT COUNT(*) FROM civic_reports WHERE user_id = p.id) AS total_reports,\r\n    (SELECT COUNT(*) FROM civic_reports WHERE user_id = p.id AND status IN ('confirmed', 'verified', 'resolved')) AS confirmed_reports\r\nFROM profiles p;\r\n\r\n-- 5. Segnalazioni in attesa di match (per pannello admin)\r\nCREATE OR REPLACE VIEW civic_reports_pending AS\r\nSELECT \r\n    cr.*,\r\n    p.nickname,\r\n    p.total_tokens\r\nFROM civic_reports cr\r\nJOIN profiles p ON cr.user_id = p.id\r\nWHERE cr.status = 'pending_match'\r\nORDER BY cr.created_at DESC;\r\n\r\n-- Verifica\r\nSELECT 'Blocco 3A completato: ' || COUNT(*) || ' viste create' AS status\r\nFROM information_schema.views \r\nWHERE table_schema = 'public' \r\n  AND table_name IN ('active_tenant_events', 'goal_progress', 'global_impact_leaderboard', 'user_badges_complete', 'civic_reports_pending');","content_id":"31e2e6b5-c577-40af-b2a6-197c4ed8de2f","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
